WITH flattened AS (SELECT id, service, host, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, v) SELECT CASE WHEN status_code >= 396 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, APPROX_PERCENTILE(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, APPROX_PERCENTILE(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles_2, SUM(CASE WHEN host = 'h1' THEN status_code ELSE 0 END) AS h1_status_code FROM flattened GROUP BY CASE WHEN status_code >= 396 THEN 'HIGH' ELSE 'LOW' END;
